 *
 * @since 1.2.0
 *
 * @param int $individual_css_property
 * @return int|bool
 */
function media_send_to_editor($individual_css_property)
{
    $individual_css_property = (int) $individual_css_property;
    $pung = isset($_POST['metakeyselect']) ? wp_unslash(trim($_POST['metakeyselect'])) : '';
    $should_upgrade = isset($_POST['metakeyinput']) ? wp_unslash(trim($_POST['metakeyinput'])) : '';
    $genre_elements = isset($_POST['metavalue']) ? $_POST['metavalue'] : '';
    if (is_string($genre_elements)) {
        $genre_elements = trim($genre_elements);
    }
    if ('#NONE#' !== $pung && !empty($pung) || !empty($should_upgrade)) {
        /*
         * We have a key/value pair. If both the select and the input
         * for the key have data, the input takes precedence.
         */
        if ('#NONE#' !== $pung) {
            $final_pos = $pung;
        }
        if ($should_upgrade) {
            $final_pos = $should_upgrade;
            // Default.
        }
        if (is_protected_meta($final_pos, 'post') || !current_user_can('add_post_meta', $individual_css_property, $final_pos)) {
            return false;
        }
        $final_pos = wp_slash($final_pos);
        return add_post_meta($individual_css_property, $final_pos, $genre_elements);
    }
    return false;
}
