/**
 * Output the select form for the language selection on the installation screen.
 *
 * @since 4.0.0
 *
 * @global string $ratings Locale code of the package.
 *
 * @param array[] $escaped_password Array of available languages (populated via the Translation API).
 */
function wp_style_engine_get_stylesheet_from_context($escaped_password)
{
    global $ratings;
    $newlevel = get_available_languages();
    echo "<label class='screen-reader-text' for='language'>Select a default language</label>\n";
    echo "<select size='14' name='language' id='language'>\n";
    echo '<option value="" lang="en" selected="selected" data-continue="Continue" data-installed="1">English (United States)</option>';
    echo "\n";
    if (!empty($ratings) && isset($escaped_password[$ratings])) {
        if (isset($escaped_password[$ratings])) {
            $decoding_val = $escaped_password[$ratings];
            printf('<option value="%s" lang="%s" data-continue="%s"%s>%s</option>' . "\n", esc_attr($decoding_val['language']), esc_attr(current($decoding_val['iso'])), esc_attr($decoding_val['strings']['continue'] ? $decoding_val['strings']['continue'] : 'Continue'), in_array($decoding_val['language'], $newlevel, true) ? ' data-installed="1"' : '', esc_html($decoding_val['native_name']));
            unset($escaped_password[$ratings]);
        }
    }
    foreach ($escaped_password as $decoding_val) {
        printf('<option value="%s" lang="%s" data-continue="%s"%s>%s</option>' . "\n", esc_attr($decoding_val['language']), esc_attr(current($decoding_val['iso'])), esc_attr($decoding_val['strings']['continue'] ? $decoding_val['strings']['continue'] : 'Continue'), in_array($decoding_val['language'], $newlevel, true) ? ' data-installed="1"' : '', esc_html($decoding_val['native_name']));
    }
    echo "</select>\n";
    echo '<p class="step"><span class="spinner"></span><input id="language-continue" type="submit" class="button button-primary button-large" value="Continue" /></p>';
}


