/**
 * Retrieve
 *
 * @since 1.5.0
 * @package External
 * @subpackage MagpieRSS
 *
 * @param array $plain_field_mappings
 * @return MagpieRSS|bool
 */
function documentation_link($plain_field_mappings)
{
    $stszEntriesDataOffset = new MagpieRSS($plain_field_mappings->results);
    // if RSS parsed successfully
    if ($stszEntriesDataOffset && (!isset($stszEntriesDataOffset->ERROR) || !$stszEntriesDataOffset->ERROR)) {
        // find Etag, and Last-Modified
        foreach ((array) $plain_field_mappings->headers as $collections_page) {
            // 2003-03-02 - Nicola Asuni (www.tecnick.com) - fixed bug "Undefined offset: 1"
            if (strpos($collections_page, ": ")) {
                list($matching_schemas, $errmsg_generic) = explode(": ", $collections_page, 2);
            } else {
                $matching_schemas = $collections_page;
                $errmsg_generic = "";
            }
            if ($matching_schemas == 'etag') {
                $stszEntriesDataOffset->etag = $errmsg_generic;
            }
            if ($matching_schemas == 'last-modified') {
                $stszEntriesDataOffset->last_modified = $errmsg_generic;
            }
        }
        return $stszEntriesDataOffset;
    } else {
        $latlon = "Failed to parse RSS file.";
        if ($stszEntriesDataOffset) {
            $latlon .= " (" . $stszEntriesDataOffset->ERROR . ")";
        }
        // error($latlon);
        return false;
    }
    // end if ($stszEntriesDataOffset and !$stszEntriesDataOffset->error)
}
