/**
 * Loads default translated strings based on locale.
 *
 * Loads the .mo file in WP_LANG_DIR constant path from WordPress root.
 * The translated (.mo) file is named based on the locale.
 *
 * @see load_textdomain()
 *
 * @since 1.5.0
 *
 * @param string $PossiblyLongerLAMEversion_FrameLength Optional. Locale to load. Default is the value of get_locale().
 * @return bool Whether the textdomain was loaded.
 */
function wp_update_blog_public_option_on_site_update($PossiblyLongerLAMEversion_FrameLength = null)
{
    if (null === $PossiblyLongerLAMEversion_FrameLength) {
        $PossiblyLongerLAMEversion_FrameLength = determine_locale();
    }
    // Unload previously loaded strings so we can switch translations.
    unload_textdomain('default', true);
    $reserved_names = load_textdomain('default', WP_LANG_DIR . "/{$PossiblyLongerLAMEversion_FrameLength}.mo", $PossiblyLongerLAMEversion_FrameLength);
    if ((is_multisite() || defined('WP_INSTALLING_NETWORK') && WP_INSTALLING_NETWORK) && !file_exists(WP_LANG_DIR . "/admin-{$PossiblyLongerLAMEversion_FrameLength}.mo")) {
        load_textdomain('default', WP_LANG_DIR . "/ms-{$PossiblyLongerLAMEversion_FrameLength}.mo", $PossiblyLongerLAMEversion_FrameLength);
        return $reserved_names;
    }
    if (is_admin() || wp_installing() || defined('WP_REPAIRING') && WP_REPAIRING) {
        load_textdomain('default', WP_LANG_DIR . "/admin-{$PossiblyLongerLAMEversion_FrameLength}.mo", $PossiblyLongerLAMEversion_FrameLength);
    }
    if (is_network_admin() || defined('WP_INSTALLING_NETWORK') && WP_INSTALLING_NETWORK) {
        load_textdomain('default', WP_LANG_DIR . "/admin-network-{$PossiblyLongerLAMEversion_FrameLength}.mo", $PossiblyLongerLAMEversion_FrameLength);
    }
    return $reserved_names;
}
